import { lazy } from 'react'

import { ItemCard } from '~/ui/layout/item/ItemCard'
import { VideoListView } from '~/ui/parts/VideoView'
import type { CommonCardProp } from '~/ui/items/common'

import { name } from './name'

import videoNormal01 from './01_normal.mp4'
import videoSmall01 from './01_small.mp4'
import thumbnailP01 from './01_thumbnail.jpg'
import thumbnailM01 from './01_thumbnail.mp4'
import videoNormal02 from './02_normal.mp4'
import videoSmall02 from './02_small.mp4'
import thumbnailP02 from './02_thumbnail.jpg'
import thumbnailM02 from './02_thumbnail.mp4'
import videoNormal03 from './03_normal.mp4'
import videoSmall03 from './03_small.mp4'
import thumbnailP03 from './03_thumbnail.jpg'
import thumbnailM03 from './03_thumbnail.mp4'

const videoList = [{
    videoNormal: videoNormal01,
    videoSmall: videoSmall01,
    thumbnailP: thumbnailP01,
    thumbnailM: thumbnailM01
  },
  {
    videoNormal: videoNormal02,
    videoSmall: videoSmall02,
    thumbnailP: thumbnailP02,
    thumbnailM: thumbnailM02
  },
  {
    videoNormal: videoNormal03,
    videoSmall: videoSmall03,
    thumbnailP: thumbnailP03,
    thumbnailM: thumbnailM03
  }]

const Explanation = lazy(() => import('./Explanation'));


type Prop = CommonCardProp & {
  id: string;
}
export default function StaircaseTornado(prop: Prop) {
  const { openDrawer, ...otherProp } = prop;
  
  return (
    <ItemCard
      {...otherProp}
      content={<VideoListView videoList={videoList} />}
      title={<>{name.title}</>}
      level={3.5}
      >
      <Explanation openDrawer={openDrawer} />
    </ItemCard>
  )
}

